pending = {}
def on_response(resp):
    request_id = resp["id"]
    resolve(pending.pop(request_id))   # assumes exactly one response per id

def build_request(request_id, method, params=None):
    req = {"jsonrpc": "2.0", "id": request_id, "method": method}
    if params is not None:
        req["params"] = params
    return req

print(build_request(3, "tools/call", {"name": "get_weather", "arguments": {"city": "Delhi"}}))
